"""Extend only thin Frugal adapter template instantiations to 192/288/384 modes."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def write(path,text):
    with (ROOT/path).open('xb') as f:f.write(text.encode())
for source,target in [('frugal_cpu73_adapter_v1.cpp','frugal_cpu75_adapter_v1.cpp'),('frugal_gpu72_host_v4.cpp','frugal_gpu75_host_v1.cpp')]:
    s=(ROOT/'native'/source).read_text(encoding='utf-8');extra=''.join(f'case {n}:run72<{n}>(cutoff,count,seed,covariance,output,timings);break;' for n in (192,288,384));s=s.replace('default:throw',extra+'default:throw').replace('supports 4,8,144 modes','supports 4,8,144,192,288,384 modes');write('native/'+target,s)
s=(ROOT/'native/frugal_gpu72_kernels_v4.cu').read_text(encoding='utf-8');anchor=s[s.index('template Result<std::vector<Bitstring<144>>>'):s.rindex('}')];s=s[:s.rindex('}')]+''.join(anchor.replace('144',str(n)) for n in (192,288,384))+'}\n';write('native/frugal_gpu75_kernels_v1.cu',s)
s=(ROOT/'experiments/iteration73_frugal_cpu_library_v1.py').read_text(encoding='utf-8');s=s.replace('frugal_cpu73_adapter_v1.cpp','frugal_cpu75_adapter_v1.cpp').replace('for bits in (32,64):','for bits in (64,):').replace('Build AVX2 C ABI with validated identical-body sum-inlining workaround.','Build expanded-dimension FP64 AVX2 C ABI; retain prior identical-body sum-inlining workaround.');write('experiments/iteration75_frugal_cpu_build_v1.py',s)
s=(ROOT/'experiments/iteration72_frugal_gpu_build_v5.py').read_text(encoding='utf-8');s=s.replace('frugal_gpu72_host_v4.cpp','frugal_gpu75_host_v1.cpp').replace('frugal_gpu72_kernels_v4.cu','frugal_gpu75_kernels_v1.cu').replace('deziro_frugal_gpu72_','deziro_frugal_gpu75_').replace('for precision in (1,2):','for precision in (2,):').replace('precision_settings=[1,2]','precision_settings=[2]').replace('Build v5:','Build expanded-dimension FP64 v1:');write('experiments/iteration75_frugal_gpu_build_v1.py',s)
s=(ROOT/'experiments/iteration75_scale_click_v1.py').read_text(encoding='utf-8');s=s.replace('iteration73_frugal_cpu_library_v1/frugal_cpu_fp64.dll','iteration75_frugal_cpu_build_v1/frugal_cpu_fp64.dll').replace('iteration72_frugal_gpu_build_v5/frugal_fp64.dll','iteration75_frugal_gpu_build_v1/frugal_fp64.dll').replace('Beyond 50 occupied inputs:','Complete rerun after adapter dimension extension; no timings spliced from v1. Beyond 50 occupied inputs:');write('experiments/iteration75_scale_click_v2.py',s)
